<?php
declare(strict_types=1);
namespace PkStore\Infrastructure\Admin;
final class DashboardService {
    private const TTL=HOUR_IN_SECONDS;
    public function __construct(private readonly \wpdb $db){}
    public function getDeliveryHealth():array{$c=get_transient('pkstore_dash_health');if($c!==false)return $c;$since=date('Y-m-d H:i:s',strtotime('-30 days'));$rows=$this->db->get_results($this->db->prepare("SELECT pm.meta_value AS courier,COUNT(DISTINCT p.ID) AS total,SUM(p.post_status='wc-completed') AS delivered,SUM(p.post_status='wc-returned') AS rto,SUM(p.post_status IN ('wc-shipped','wc-out-for-delivery')) AS in_transit FROM {$this->db->posts} p INNER JOIN {$this->db->postmeta} pm ON p.ID=pm.post_id AND pm.meta_key='_booked_courier' WHERE p.post_type='shop_order' AND p.post_date>=%s GROUP BY pm.meta_value",$since),ARRAY_A)?:[];$r=[];foreach($rows as $row){$t=max(1,(int)$row['total']);$d=(int)$row['delivered'];$rt=(int)$row['rto'];$r[$row['courier']]=['courier'=>strtoupper($row['courier']),'total'=>$t,'delivered'=>$d,'rto'=>$rt,'in_transit'=>(int)$row['in_transit'],'delivery_rate'=>round(($d/$t)*100,1),'rto_rate'=>round(($rt/$t)*100,1)];}set_transient('pkstore_dash_health',$r,self::TTL);return $r;}
    public function getLogisticsSummary():array{$c=get_transient('pkstore_dash_logistics');if($c!==false)return $c;$today=date('Y-m-d 00:00:00');$h24=date('Y-m-d H:i:s',strtotime('-24 hours'));$t=$this->db->prefix.'pkstore_logistics_log';$r=['total_today'=>(int)$this->db->get_var($this->db->prepare("SELECT COUNT(*) FROM {$this->db->posts} WHERE post_type='shop_order' AND post_date>=%s",$today)),'pending_booking'=>(int)$this->db->get_var("SELECT COUNT(*) FROM {$this->db->postmeta} WHERE meta_key='_tracking_courier' AND meta_value LIKE 'PENDING-%'"),'booking_failures_24h'=>(int)$this->db->get_var($this->db->prepare("SELECT COUNT(*) FROM {$t} WHERE log_type='failure' AND created_at>=%s",$h24)),'avg_api_response_ms'=>(int)$this->db->get_var($this->db->prepare("SELECT COALESCE(AVG(duration_ms),0) FROM {$t} WHERE log_type='response' AND created_at>=%s",$h24))];set_transient('pkstore_dash_logistics',$r,self::TTL);return $r;}
    public function getOtpSummary():array{$c=get_transient('pkstore_dash_otp');if($c!==false)return $c;$h24=date('Y-m-d H:i:s',strtotime('-24 hours'));$t=$this->db->prefix.'pkstore_otp_attempts';$row=$this->db->get_row($this->db->prepare("SELECT COUNT(*) AS total,SUM(is_verified=1) AS verified FROM {$t} WHERE created_at>=%s",$h24),ARRAY_A);$total=max(1,(int)($row['total']??0));$v=(int)($row['verified']??0);$r=['total_24h'=>$total,'verified_24h'=>$v,'verification_rate'=>round(($v/$total)*100,1)];set_transient('pkstore_dash_otp',$r,self::TTL);return $r;}
    public function getAiSummary():array{$c=get_transient('pkstore_dash_ai');if($c!==false)return $c;$h24=date('Y-m-d H:i:s',strtotime('-24 hours'));$t=$this->db->prefix.'pkstore_chat_history';$row=$this->db->get_row($this->db->prepare("SELECT COUNT(DISTINCT session_uuid) AS sessions,COUNT(*) AS messages FROM {$t} WHERE created_at>=%s",$h24),ARRAY_A);$s=max(1,(int)($row['sessions']??0));$m=(int)($row['messages']??0);$r=['total_sessions_24h'=>$s,'total_messages_24h'=>$m,'avg_messages_per_session'=>round($m/$s,1)];set_transient('pkstore_dash_ai',$r,self::TTL);return $r;}
    public function bustAllCaches():void{foreach(['pkstore_dash_health','pkstore_dash_logistics','pkstore_dash_otp','pkstore_dash_ai']as $k)delete_transient($k);}
}
